#!/usr/bin/env node
// Generates DESIGN.md (Google Stitch DESIGN.md format) and the README regions
// `component-inventory` and `deprecated-aliases` from the real tokens and sources.
//
//   node scripts/gen-design-md.mjs            write DESIGN.md and README.md
//   node scripts/gen-design-md.mjs --check    write nothing; exit 1 if either would change
//   --design <path> / --readme <path>         override the output paths (tests use temp copies)
//
// Inputs: packages/tokens/src/tokens.json, packages/tokens/dist/theme.css and dist/index.d.ts
// (both generated by packages/tokens/build.js), the Svelte component sources, both package
// index files and COMPONENTS from scripts/parity-check.mjs.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { COMPONENTS } from './parity-check.mjs';
import { buildModel } from './design-md/model.mjs';
import { renderDesignMd, renderInventory, renderAliases, replaceRegion } from './design-md/render.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => fs.readFileSync(path.resolve(root, p), 'utf8');

/** Component names exported by each package index, with a flag for parity gating. */
export function inventory({ svelteIndex, reactIndex, components }) {
  const svelte = new Set([...svelteIndex.matchAll(/export \{ default as (\w+) \} from '\.\/\w+\.svelte'/g)].map((m) => m[1]));
  const react = new Set([...reactIndex.matchAll(/export \{ ([A-Z]\w*)[,\s]/g)].map((m) => m[1]));
  const gated = new Set(components);
  return [...new Set([...svelte, ...react])]
    .sort((a, b) => a.localeCompare(b))
    .map((name) => ({ name, svelte: svelte.has(name), react: react.has(name), gated: gated.has(name) }));
}

export function generate() {
  const sources = Object.fromEntries(COMPONENTS.map((c) => [c, read(`packages/svelte/src/lib/${c}.svelte`)]));
  const model = buildModel({
    tokens: JSON.parse(read('packages/tokens/src/tokens.json')),
    themeCss: read('packages/tokens/dist/theme.css'),
    dts: read('packages/tokens/dist/index.d.ts'),
    components: COMPONENTS,
    sources
  });
  const inv = inventory({ svelteIndex: read('packages/svelte/src/lib/index.ts'), reactIndex: read('packages/react/src/index.ts'), components: COMPONENTS });
  return { designMd: renderDesignMd(model), inventoryMd: renderInventory(inv), aliasesMd: renderAliases(model.deprecatedAliases) };
}

function main(argv) {
  const check = argv.includes('--check');
  const opt = (flag, fallback) => (argv.includes(flag) ? path.resolve(argv[argv.indexOf(flag) + 1]) : path.resolve(root, fallback));
  const designPath = opt('--design', 'DESIGN.md');
  const readmePath = opt('--readme', 'README.md');

  const { designMd, inventoryMd, aliasesMd } = generate();
  const readmeNow = fs.readFileSync(readmePath, 'utf8');
  const readmeNext = replaceRegion(replaceRegion(readmeNow, 'component-inventory', inventoryMd), 'deprecated-aliases', aliasesMd);
  const designNow = fs.existsSync(designPath) ? fs.readFileSync(designPath, 'utf8') : null;

  const drift = [];
  if (designNow !== designMd) drift.push(path.relative(root, designPath) || designPath);
  if (readmeNow !== readmeNext) drift.push(path.relative(root, readmePath) || readmePath);

  if (check) {
    if (drift.length) {
      console.error(`FAIL gen-design-md: out of date: ${drift.join(', ')}. Run: node scripts/gen-design-md.mjs`);
      process.exit(1);
    }
    console.log('PASS gen-design-md: DESIGN.md and README generated regions are up to date.');
    return;
  }
  if (designNow !== designMd) fs.writeFileSync(designPath, designMd);
  if (readmeNow !== readmeNext) fs.writeFileSync(readmePath, readmeNext);
  console.log(drift.length ? `gen-design-md: wrote ${drift.join(', ')}` : 'gen-design-md: already up to date');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main(process.argv.slice(2));
